// SPDX-License-Identifier: CC0-1.0
#include HEADER
#include <cstdio>
#include <random>
#include <algorithm>
#include <vector>
#include <cstdint>
#include <limits>
static std::size_t cases=0, calls=0;
static void print(const std::vector<P>&p,bool sorted){
 ++calls;
 try{const auto r=sorted?nearest_two_points_sorted(p):nearest_two_points(p);if(!r)std::puts("empty");else std::printf("%ju %ju %ju\n",std::uintmax_t(r->distance_squared),std::uintmax_t(r->first_index),std::uintmax_t(r->second_index));}catch(const std::overflow_error&){std::puts("overflow");}
}
int main(){
 std::vector<std::size_t>sizes;for(std::size_t n=0;n<=96;++n)sizes.push_back(n);for(std::size_t n:{127,128,129,255,256,257,511,512,513,1023,1024,1025,2047,2048,2049,4095,4096,4097,8191,8192,8193,9999,10001,16383,16384,16385})sizes.push_back(n);
 for(std::uint64_t seed=0;seed<4;++seed){std::mt19937_64 rng(seed*UINT64_C(913728571)+41);
  for(auto n:sizes)for(unsigned shape=0;shape<10;++shape){
   std::vector<P>p;p.reserve(n);
   for(std::size_t i=0;i<n;++i){std::int32_t x=std::int32_t(rng()),y=std::int32_t(rng());
    if(shape==1){x=std::int32_t(rng()%9)-4;y=std::int32_t(rng()%9)-4;}
    if(shape==2){x=std::int32_t(i*97);y=7;}
    if(shape==3){x=7;y=std::int32_t(i*97);}
    if(shape==4){x=std::int32_t(i%61)*1001;y=std::int32_t(i/61)*1001;}
    if(shape==5){x=std::int32_t(i/4)*1000;y=std::int32_t(i%4)*1000;}
    if(shape==6){x=(i&1)?std::numeric_limits<std::int32_t>::max()-std::int32_t(i/2):std::numeric_limits<std::int32_t>::min()+std::int32_t(i/2);y=(i%3)?-37:37;}
    if(shape==7){x=std::int32_t(i*83);y=(i%4)?0:std::int32_t(i*91);}
    if(shape==8){x=std::int32_t(rng()%5);y=std::int32_t(i*47);}
    if(shape==9){x=std::int32_t(i*47);y=std::int32_t(rng()%5);}
    p.emplace_back(x,y);
   }
   std::shuffle(p.begin(),p.end(),rng);if(n>2&&shape==7){p[n/2]=p[0];}
   ++cases;print(p,false);std::sort(p.begin(),p.end());print(p,true);
  }
 }
 std::fprintf(stderr,"PASS generated=%ju APIcalls=%ju\n",std::uintmax_t(cases),std::uintmax_t(calls));
}

